require_once __DIR__ . '/../includes/config.php';
require_role(['student','host','coordinator','volunteer']);db_required();$s=$pdo->prepare('SELECT va.*,e.title FROM volunteer_applications va JOIN events e ON e.id=va.event_id WHERE va.user_id=? ORDER BY va.created_at DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll();$page_title='Volunteer Dashboard';require __DIR__.'/../includes/header.php';?><div class="container py-5"><div class="d-flex justify-content-between mb-4"><div><div class="section-kicker">Volunteer</div><h2 class="fw-bold">My applications</h2></div><a href="/volunteer/apply.php" class="btn btn-primary rounded-pill">Apply for an event</a></div><div class="dash-card overflow-hidden"><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>Event</th><th>Position</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['position'])?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="3" class="empty">No volunteer applications yet.</td></tr><?php endif;?></tbody></table></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
